// Mirrors categorizeError in scripts/lib/agent-core.mjs. Sanitization: keep only
// technical metadata — never message content, phone numbers, or raw records.
const e = $json;
const exec = e.execution || {};
const wfName = (e.workflow && e.workflow.name) || 'unknown';
const lastNode = (exec.lastNodeExecuted) || 'unknown';
const errObj = (exec.error) || {};
const msg = String(errObj.message || '').slice(0, 300);
const status = Number((errObj.httpCode) || (msg.match(/\b(4\d\d|5\d\d)\b/) || [])[0] || 0);
function categorize(sc, timeout) {
  if (sc === 401 || sc === 403) return { category: 'auth', retryable: false, alert: true };
  if (sc === 429) return { category: 'rate_limit', retryable: true, alert: true };
  if (sc >= 500) return { category: 'upstream_5xx', retryable: true, alert: false };
  if (sc === 408 || timeout) return { category: 'timeout', retryable: true, alert: false };
  if (sc >= 400) return { category: 'client_error', retryable: false, alert: false };
  return { category: 'unknown', retryable: false, alert: true };
}
const cat = categorize(status, /timeout|timed out/i.test(msg));
// Redact anything that looks like a phone number, SSN, or long digit run in the message.
const sanitized = msg.replace(/\+?\d[\d\s().-]{7,}\d/g, '[REDACTED-NUM]').replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[REDACTED]');
const correlation = (() => { try { const data = JSON.stringify(exec).match(/emma_[a-z0-9_]+|fu_[a-z0-9_]+|resume_[a-z0-9]+/); return data ? data[0] : null; } catch { return null; } })();
const handle = (() => { try { const data = JSON.stringify(exec).match(/"message_handle"\s*:\s*"([^"]{4,80})"/); return data ? data[1] : null; } catch { return null; } })();
const isSendNode = wfName.startsWith('SB-06') && /send/i.test(lastNode);
return [{ json: {
  event_id: 'dlq_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 6),
  correlation_id: correlation, workflow_name: wfName, workflow_version: '1.0.0',
  execution_id: String(exec.id || ''), failed_node: lastNode,
  category: cat.category, retryable: cat.retryable, alert: cat.alert,
  error_code: String(status || errObj.name || 'unknown'), sanitized_summary: sanitized,
  message_handle: handle,
  replayable: cat.retryable && !isSendNode,
  replay_note: isSendNode ? 'NEVER replay: send node — the message may have been accepted by Sendblue; idempotency table is authoritative' : null,
  created_at: new Date().toISOString()
} }];

// Group repetitive alerts: use workflow static data to suppress duplicates of
// the same workflow+category within a 10-minute window.
const j = $json;
const staticData = $getWorkflowStaticData('global');
const key = j.workflow_name + '|' + j.category;
const now = Date.now();
staticData.alerts = staticData.alerts || {};
const prev = staticData.alerts[key] || { count: 0, first: now, lastSent: 0 };
prev.count += 1;
let send = false;
if (j.alert || j.category === 'auth') {
  if (now - prev.lastSent > 10 * 60 * 1000) { send = true; prev.lastSent = now; }
}
staticData.alerts[key] = prev;
if (!send) return [];
return [{ json: { ...j, grouped_count: prev.count } }];

