// Replay is safe because: (1) only replayable events (never accepted sends),
// (2) SB-01/SB-06 idempotency claims still stand — a replayed inbound event that
// was already processed dedupes on message_handle; a replayed dispatch dedupes
// on its idempotency key. Requires the ops token.
const body = $json.body || {};
const headers = $json.headers || {};
const token = headers['x-replay-token'] || body.token || '';
const expected = $env.REPLAY_AUTH_TOKEN || '';
let ok = expected.length > 0 && token.length === expected.length;
if (ok) { let d = 0; for (let i = 0; i < expected.length; i++) d |= expected.charCodeAt(i) ^ token.charCodeAt(i); ok = d === 0; }
return [{ json: { authorized: ok, event_id: body.event_id || null } }];

// Refuses: non-replayable events, already-replayed events, and anything whose
// message_handle exists in outbound_idempotency as accepted_by_sendblue.
const rows = $input.all().map(i => i.json);
const ev = rows.find(r => r.event_id);
if (!ev) return [{ json: { replay: false, reason: 'event not found', http: 404 } }];
if (ev.replayable !== true && String(ev.replayable) !== 'true') return [{ json: { replay: false, reason: 'event is not replayable (possibly an accepted send)', http: 409 } }];
if (ev.replayed_at) return [{ json: { replay: false, reason: 'already replayed at ' + ev.replayed_at, http: 409 } }];
return [{ json: { replay: true, event: ev, http: 200 } }];
